// Findet Zeilen, denen das Vorlagen-Datum fehlt, obwohl echte Dokumente vorhanden sind.
// Zwei unabhaengige Faelle, beide gehoeren hierher:
//
// 1. documentCount (zuletzt bei Extraktion gesehene Anzahl) != documentsJson.length
//    (aktueller P1-Scrape) - ALLRIS hat nachtraeglich Dokumente hinzugefuegt, seit
//    zuletzt extrahiert wurde.
// 2. vorlageDatum ist leer, obwohl documentCount > 1 - typischerweise ein Ueberbleibsel
//    der alten Truncation-Reihenfolge (grosse Anlage vor dem eigentlichen Vorlagen-
//    dokument liess das 60.000-Zeichen-Limit den Datumskopf nie erreichen, siehe die
//    P3-Truncation-Fix vom 2026-07-30; live gefunden an 2026/060, wo documentCount UND
//    documentsJson.length beide 9 sind - Fall 1 haette das nicht erfasst).
//
// Nur contentStage=content_posted (fertig, nicht mehr aktiv in P3/P4 Bearbeitung), um
// keine Race mit laufender Verarbeitung zu riskieren.
function safeInt(v) { const n = parseInt(String(v || '0'), 10); return Number.isFinite(n) ? n : 0; }
function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }

const items = $input.all();
const out = [];
for (const item of items) {
  const j = item.json || {};
  if (j.contentStage !== 'content_posted') continue;
  if (!j.nextcloudFolder) continue;
  let docs = [];
  try { docs = JSON.parse(j.documentsJson || '[]'); } catch (e) { continue; }
  if (docs.length === 0) continue;
  const storedCount = safeInt(j.documentCount);

  const countMismatch = storedCount !== docs.length;
  const missingDateDespiteDocs = !safeStr(j.vorlageDatum) && docs.length > 1;
  if (!countMismatch && !missingDateDespiteDocs) continue;

  out.push({ json: { ...j, _storedCount: storedCount, _expectedCount: docs.length, _reason: countMismatch ? 'count_mismatch' : 'missing_date' } });
}
console.log('[Metadaten-Nachzieher] ' + out.length + ' Vorgaenge gefunden.');
return out;

return $input.all().filter(item => {
  const p = String(item.json.path || '').toLowerCase();
  return p.endsWith('.pdf') && item.json.type !== 'dir' && !item.json.isDirectory;
}).map(item => ({ json: { ...item.json, path: decodeURIComponent(item.json.path) } }));

const current = $input.item.json || {};
let source = {};
try { source = $('NC Download').item.json || {}; } catch(e) {}
let text = current.body ?? current.data ?? current.text ?? current.response ?? current.result ?? current.content ?? '';
if (typeof text !== 'string') text = JSON.stringify(text);
text = String(text || '').replace(/\u0000/g, '').replace(/[ \t]+/g, ' ').replace(/\r\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
const fileName = source.path ? source.path.split('/').pop() : 'Dokument';
const extractionOk = text.length > 80;
return { json: { _fileName: fileName, _extractedText: extractionOk ? text.substring(0, 50000) : '', extractionOk } };

// Fasst alle in dieser Schleifen-Runde extrahierten Dokumenttexte fuer GENAU EINEN
// Vorgang zusammen (Loop-Kontext = batchSize:1, daher keine Vermischung moeglich).
// Datum PRO Dokument suchen (nicht erst zusammenkleben+kuerzen - siehe P3-Truncation-
// Fix vom 2026-07-30). Aktualisiert zusaetzlich documentCount auf die tatsaechlich
// gefundene Dateizahl, damit dieselbe Zeile beim naechsten Lauf nicht wieder auftaucht.
// Nur Metadatenfelder (+documentCount) werden veraendert - AI-generierter Content
// bleibt unangetastet (Nutzerentscheidung 2026-07-30).
function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }

const ziel = $('Loop Vorgang (1x)').item.json;
const items = $input.all();

function extractVorlagenMeta(text) {
  const t = safeStr(text);
  const verfasserMatch = t.match(/([^\n]+)\n\s*Verfasser\/in/);
  const datumMatch = t.match(/Stadt Goslar Goslar,\s*(\d{1,2})\.(\d{1,2})\.(\d{4})/);
  let fachdienst = '';
  if (datumMatch) {
    const rest = t.slice(datumMatch.index + datumMatch[0].length);
    const fdMatch = rest.match(/^\s*\n([^\n]+)\n/);
    if (fdMatch) fachdienst = fdMatch[1].trim();
  }
  const vorlageDatumPdf = datumMatch
    ? `${datumMatch[3]}-${datumMatch[2].padStart(2, '0')}-${datumMatch[1].padStart(2, '0')}`
    : '';
  return { verfasser: verfasserMatch ? verfasserMatch[1].trim() : '', fachdienst, vorlageDatumPdf };
}

let meta = { verfasser: '', fachdienst: '', vorlageDatumPdf: '' };
for (const item of items) {
  if (!item.json.extractionOk) continue;
  const m = extractVorlagenMeta(item.json._extractedText);
  if (m.vorlageDatumPdf) { meta = m; break; }
}

return [{ json: {
  ...ziel,
  documentCount: items.length,
  verfasser: meta.verfasser || ziel.verfasser || '',
  fachdienst: meta.fachdienst || ziel.fachdienst || '',
  vorlageDatumPdf: meta.vorlageDatumPdf || ziel.vorlageDatumPdf || '',
  vorlageDatum: meta.vorlageDatumPdf || ziel.vorlageDatum || ziel.vorlageDatumWeb || '',
  _reextractFilesFound: items.length,
  _reextractFilesOk: items.filter(i => i.json.extractionOk).length,
  _reextractDatumFound: !!meta.vorlageDatumPdf
} }];

const j = $json;
return { json: {
  ...j,
  claimAction: 'acquire',
  claimOwner: 'ALLRIS_P4b_Metadaten_Nachzieher:' + $execution.id,
  claimStage: 'metadata_nachzug',
  leaseMinutes: 15,
  expectedClaimOwner: j.claim_owner ?? null,
  expectedClaimExpiresAt: j.claim_expires_at ?? null
} };

const ziel = $('Bereite Claim vor').item.json;
const id = ziel.id;
const vorgangKey = String(ziel.vorgangKey || '').trim();
if (!vorgangKey) throw new Error('[P4b Claim Release] vorgangKey fehlt.');
if (!id) throw new Error('[P4b Claim Release] id fehlt - Release-Matching in ALLRIS_Claim_Lease braucht id + claim_owner.');
return { json: { id, vorgangKey, claimAction: 'release', claimOwner: 'ALLRIS_P4b_Metadaten_Nachzieher:' + $execution.id } };
